   626	func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
   627		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
   628		if err != nil {
   629			return staleReport{}, err
   630		}
   631		if !local {
   632			return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
   633		}
   634		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
   635		if err != nil {
   636			return staleReport{}, err
   637		}
   638		manifest, err := loadBrainManifest(storage.BrainDir)
   639		if err != nil {
   640			return staleReport{}, err
   641		}
   642		axes := map[string]staleAxis{}
   643		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
   644			axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
   645			return staleReport{Severity: "unsafe", Axes: axes}, nil
   646		}
   647		source := manifest.Sources.Semantic
   648		head, _ := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
   649		branch, _ := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
   650		dirty := worktreeDirty(ctx, opts.Runner, repoDir)
   651		if source.Commit == head {
   652			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
   653		} else {
   654			axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
   655		}
   656		if source.Branch == "" || source.Branch == branch {
   657			axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
   658		} else {
   659			axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
   660		}
   661		switch {
   662		case dirty && source.WorktreeMode != "worktree":
   663			axes["worktree"] = staleAxis{State: "dirty-unindexed", Detail: "semantic index is based on committed HEAD"}
   664		case dirty && source.WorktreeHash != "" && source.WorktreeHash != worktreeFingerprint(ctx, opts.Runner, repoDir):
   665			axes["worktree"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since semantic indexing"}
   666		case dirty:
   667			axes["worktree"] = staleAxis{State: "dirty-indexed"}
   668		case source.WorktreeMode == "worktree":
   669			axes["worktree"] = staleAxis{State: "worktree-overlay-stale", Detail: "active semantic index was built from dirty content but worktree is now clean"}
   670		default:
   671			axes["worktree"] = staleAxis{State: "clean"}
   672		}
   673		if err := validateSemanticSchema(source.SchemaVersion); err != nil {
   674			axes["provider"] = staleAxis{State: "unsafe", Detail: err.Error()}
   675		} else if !source.NoEgressVerified {
   676			axes["provider"] = staleAxis{State: "degraded", Detail: "provider no-egress status was not verified"}
   677		} else {
   678			axes["provider"] = staleAxis{State: "ok", Detail: source.Provider + " " + source.ProviderVersion}
   679		}
   680		if len(source.PartialFailures) > 0 {
   681			axes["semantic_completeness"] = staleAxis{State: "degraded", Detail: strconv.Itoa(len(source.PartialFailures)) + " partial failures"}
   682		} else {
   683			axes["semantic_completeness"] = staleAxis{State: "ok"}
   684		}
   685		severity := aggregateStaleSeverity(axes)
   686		return staleReport{Severity: severity, Axes: axes, Warnings: source.Warnings}, nil
   687	}
   688	
   689	func aggregateStaleSeverity(axes map[string]staleAxis) string {
   690		severity := "ok"
   691		for _, axis := range axes {
   692			switch axis.State {
   693			case "missing", "unsafe", "stale", "dirty-stale", "worktree-overlay-stale":
   694				return "unsafe"
   695			case "degraded", "dirty-unindexed":
   696				severity = "degraded"
   697			}
   698		}
   699		return severity
   700	}
