   769	func findSemanticSymbols(snapshotPath, query string, limit int) ([]semanticRecord, error) {
   770		f, err := os.Open(snapshotPath)
   771		if err != nil {
   772			return nil, fmt.Errorf("open semantic snapshot: %w", err)
   773		}
   774		defer f.Close()
   775		query = strings.ToLower(strings.TrimSpace(query))
   776		scanner := bufio.NewScanner(f)
   777		scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
   778		first := true
   779		var results []semanticRecord
   780		for scanner.Scan() {
   781			if first {
   782				first = false
   783				continue
   784			}
   785			var record semanticRecord
   786			if err := json.Unmarshal(scanner.Bytes(), &record); err != nil {
   787				return nil, err
   788			}
   789			if record.RecordType != "symbol" {
   790				continue
   791			}
   792			fields := []string{record.Name, record.QualifiedName, record.Signature, record.FilePath}
   793			for _, field := range fields {
   794				if strings.Contains(strings.ToLower(field), query) {
   795					results = append(results, record)
   796					break
   797				}
   798			}
   799			if len(results) >= limit {
   800				break
   801			}
   802		}
   803		return results, scanner.Err()
   804	}
