   851		active := ""
   852		if manifest != nil && manifest.Sources != nil && manifest.Sources.Semantic != nil {
   853			active = filepath.Clean(filepath.Join(storage.BrainDir, filepath.FromSlash(manifest.Sources.Semantic.SnapshotPath), ".."))
