   860				return nil
   861			}
   862			return err
   863		}
   864		pruned := 0
   865		for _, entry := range entries {
   866			if !entry.IsDir() {
   867				continue
   868			}
   869			path := filepath.Join(snapshotsRoot, entry.Name())
   870			if active != "" && filepath.Clean(path) == active {
