   888	func parseAgeCutoff(value string, now time.Time) (time.Time, error) {
   889		value = strings.TrimSpace(value)
   890		if strings.HasSuffix(value, "d") {
   891			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
   892			if err != nil || days < 0 {
   893				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
   894			}
   895			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
   896		}
   897		duration, err := time.ParseDuration(value)
   898		if err != nil {
   899			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
   900		}
   901		return now.Add(-duration), nil
   902	}
