  1319	func promptSeedTimeoutAction(opts seedCommandOptions, timeout time.Duration, fallback string) string {
  1320		if opts.noInteractive || !stdinIsTerminal() {
  1321			return fallback
  1322		}
  1323		fmt.Fprintf(os.Stderr, "Deep synthesis has been running for %s. Keep quick result, continue, or fail?\n[k]eep quick / [c]ontinue / [f]ail: ", timeout)
  1324		var response string
  1325		if _, err := fmt.Fscanln(os.Stdin, &response); err != nil {
  1326			return fallback
  1327		}
  1328		switch strings.ToLower(strings.TrimSpace(response)) {
  1329		case "c", "continue":
  1330			return "continue"
  1331		case "f", "fail":
  1332			return "fail"
  1333		default:
  1334			return "keep-quick"
  1335		}
  1336	}
