  1363	func seedAgentOutputSchema() string {
  1364		return `{"type":"object","required":["schema_version","status","model","artifacts","warnings"],"properties":{"schema_version":{"type":"integer"},"status":{"type":"string"},"model":{"type":"string"},"artifacts":{"type":"object","additionalProperties":{"type":"string"}},"warnings":{"type":"array","items":{"type":"string"}}},"additionalProperties":false}`
  1365	}
  1366	
  1367	func writeSeedAgentOutputSchema() (string, error) {
  1368		f, err := os.CreateTemp("", "entire-brain-seed-schema-*.json")
  1369		if err != nil {
  1370			return "", fmt.Errorf("create seed agent output schema: %w", err)
  1371		}
  1372		name := f.Name()
  1373		if _, err := f.WriteString(seedAgentOutputSchema()); err != nil {
  1374			_ = f.Close()
  1375			return "", fmt.Errorf("write seed agent output schema: %w", err)
  1376		}
  1377		if err := f.Chmod(0o600); err != nil {
  1378			_ = f.Close()
  1379			return "", fmt.Errorf("chmod seed agent output schema: %w", err)
  1380		}
  1381		if err := f.Close(); err != nil {
  1382			return "", fmt.Errorf("close seed agent output schema: %w", err)
  1383		}
  1384		return name, nil
  1385	}
